-- 012: toda Filipinas — destinos, centros del directorio y puntos de buceo
create table if not exists public.destinations (
  name text primary key,
  province text not null,
  island_group text not null,
  lat double precision not null,
  lng double precision not null
);
alter table public.destinations enable row level security;
create policy destinations_read on public.destinations for select using (true);
grant select on public.destinations to anon, authenticated;

alter table public.centers
  add column if not exists destination text references public.destinations(name) on update cascade,
  add column if not exists province text;
alter table public.dive_sites
  add column if not exists province text,
  add column if not exists highlight text;

