  ('Oryoku Maru', 'Subic', 'Zambales', 15, 20, 'open_water', 'WWII ''hell ship'' wreck'),
  ('Manta Bowl (Ticao Pass)', 'Donsol', 'Sorsogon', 15, 25, 'advanced', 'Strong-current manta site; whale sharks possible'),
  ('Sunken Cemetery', 'Camiguin', 'Camiguin', 5, 20, 'open_water', 'Cemetery sunk by volcano, marked by a giant cross'),
  ('Old Volcano (Old Vulcan)', 'Camiguin', 'Camiguin', 5, 30, 'open_water', 'Lava flows covered in corals'),
  ('White Island', 'Camiguin', 'Camiguin', 5, 20, 'open_water', 'Reef around the white sandbar'),
  ('Mantigue Island', 'Camiguin', 'Camiguin', 5, 30, 'open_water', 'Marine sanctuary with turtles and coral'),
  ('Tangub Bay', 'Camiguin', 'Camiguin', null, null, 'open_water', 'Hot spring reef and coral'),
  ('Daku Island', 'Siargao', 'Surigao del Norte', null, null, 'open_water', 'Coral reefs around Daku Island'),
  ('Mansud Wall', 'Siargao', 'Surigao del Norte', null, null, 'open_water', 'Wall dive'),
  ('Marissa Reef', 'Davao', 'Davao', 5, 20, 'open_water', 'Samal reef with corals and reef fish'),
  ('Ligid Caves', 'Davao', 'Davao', 5, 25, 'open_water', 'Caves and overhangs off Talikud'),
  ('Small Ligid', 'Davao', 'Davao', 5, 25, 'open_water', 'Coral-covered islet reef'),
  ('Pindawon Wall', 'Davao', 'Davao', 5, 30, 'open_water', 'Wall dive near Samal')
), upd as (
  update public.dive_sites s set province = v.province, min_depth_m = coalesce(s.min_depth_m, v.min_d), max_depth_m = coalesce(s.max_depth_m, v.max_d), highlight = v.highlight
    from v where lower(s.name) = lower(v.name)
  returning s.name
)
insert into public.dive_sites (name, area, province, min_depth_m, max_depth_m, recommended_min, highlight)
select v.name, v.area, v.province, v.min_d, v.max_d, v.lvl::cert_level, v.highlight from v
where not exists (select 1 from public.dive_sites s where lower(s.name) = lower(v.name));
update public.dive_sites set province = 'Bohol' where province is null and area in ('Panglao', 'Balicasag', 'Pamilacan', 'Anda', 'Cabilao');

-- La vista pública expone destino y provincia del centro
create or replace view public.published_trips with (security_invoker = true) as
 select t.id,
    t.center_id,
    t.departs_at,
    t.num_dives,
    t.min_level,
    t.price_php,
    t.gear_rental_php,
    c.name as center_name,
    bo.name as boat_name,
    array(select ds.name
           from trip_sites ts
             join dive_sites ds on ds.id = ts.site_id
          where ts.trip_id = t.id
          order by ts."position") as sites,
    app_available_seats(t.id) as available_seats,
    c.area as center_area,
    c.locality as center_locality,
    c.lat as center_lat,
    c.lng as center_lng,
    trip_booked_seats(t.id) as booked_seats,
    c.destination as center_destination,
    c.province as center_province
   from trips t
     join centers c on c.id = t.center_id
     join boats bo on bo.id = t.boat_id
  where t.status = 'published'::trip_status;
